INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('b2f2e7d3552a48442534af86', 'l-l-bean', 'L.L.Bean', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/58f4640011088508b7019e0e8a94a983c5ac643e280073d3b8b2d05cfc353d0d.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/l-l-bean', 'https://llbean.com/', 'llbean.com', 'Yeti Rambler Travel Bottle, 16 oz. Navy, Stainless Steel', 'The perfect commuter mug. Made from durable stainless steel with double-wall vacuum insulation, it keeps drinks hot or cold all day. Innovative, leakproof Commuter Cap offers convenient 360° drinking. Dishwasher safe. Dishwasher safe. Made from super-durable 18/8 stainless steel. Made from super-durable 18/8 stainless steel. Cup holder compatible. Leakproof Commuter Cap prevents spills in your car or inside a pack. 360° drinking cap lets you drink from any angle. Cup holder compatible. 360° drinking cap lets you drink from any angle. Leakproof Commuter Cap prevents spills in your car or inside a pack. Imported. | Yeti Rambler Travel Bottle, 16 oz. Navy, Stainless Steel', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/113abd312a7690388531b445aed555db97ebcb86c721731d4e281d919ac0f458.webp', '2026-08-19', 2);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('262d02e1591ac4a74583530e', 'vistaprint-us', 'VistaPrint US', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/85b2e9d16aa21ad8298d7702a89e05f88939d2c57bfcfa3f738d8fc6389b0eed.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/vistaprint-us', 'https://www.vistaprint.com/photo-gifts/custom-mugs-glassware-drinkware/ceramic-lined-water-bottles', 'vistaprint.com', 'Ceramic-Lined Water Bottles', '- 20 oz. capacity - Ceramic-lined interior, stainless steel exterior - Contents stay cold for up to 24 hours - Leak-proof, flip-straw lid - Sweat-free exterior - Fits most cup holders Decoration: Laser etched to reveal the stainless steel material underneath your chosen bottle color. Care Instructions: Dishwasher safe. Note: For best results, use text or graphic-based designs. We do not recommend using photos. Smart, sleek design Introducing a water bottle as adventurous as you. Loved for their superior design, RTIC 20 oz. water bottles are specially made for your longest road trips, wildest camping excursions and more. Along with premium, BPA-free materials, you’ll love ingenious features like a sweat-free surface and a flip-straw lid that stops leaks in their tracks. A recessed handle clips to bags and backpacks to free up your hands – and snaps back into place when you’re done. Buh-bye metallic taste There’s nothing like icy water on a hot hike or sweaty jog, and RTIC sports bottles deliver. The vacuum-insulated stainless steel keeps beverages cold for up to 24 hours while an airtight seal locks in chilly temps. The best part? A ceramic lining prevents drinks from developing a metallic smell or flavor, so water tastes pure till the last drop. Low cost & customizable With its stylish look and our design options, it’s easy to create a custom RTIC 20 oz. water bottle you’ll be dying to show off. Select from 6 fresh colors, then head into the studio to add a name, special quote or date to your bottle. We’ll use high-tech lasers to etch your design, leaving your bottle with sharp details. With our unbelievable pricing, you can even customize ceramic-lined water bottles for your whole crew – and give a gift that keeps them cool.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/19be23b0b115e786e09770fee87317b0ef36ecfb1678ea3aaaf5d8045e6b52ad.webp', '2026-08-19', 2);
