INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('efc8e7faaf84c811300c0738', 'vistaprint', 'VistaPrint', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/85b2e9d16aa21ad8298d7702a89e05f88939d2c57bfcfa3f738d8fc6389b0eed.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/vistaprint', 'https://www.vistaprint.com/promotional-products/drinkware/travel-mugs-tumblers-cups/hydro-flask-r-stainless-steel-insulated-coffee-mug-12-oz', 'vistaprint.com', 'Hydro Flask® Stainless Steel Insulated Coffee Mug – 12 oz.', 'Elevate your daily caffeine ritual with an insulated mug designed for warmth and convenience. With TempShield™ insulation and a closeable lid, your beverage maintains its temperature for hours, suited for both bustling mornings and leisurely afternoons. It’s easy to customize – add your logo, message or info using our intuitive studio. Need a hand? Our design experts are here to help bring your ideas to life.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/313a7a9b4d7b712cf5326b896fa0d880720bf54decd4feb83fa56b0e2dc512c8.webp', '2026-08-11', 2);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('5f635e0873ea0318e9173e2e', 'l-l-bean', 'L.L.Bean', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/58f4640011088508b7019e0e8a94a983c5ac643e280073d3b8b2d05cfc353d0d.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/l-l-bean', 'https://llbean.com/', 'llbean.com', 'Yeti Rambler Tumbler With MagSlide Lid, 20 oz. Navy, Stainless Steel', 'The Yeti Rambler is tough enough to keep up with the most intense of your outdoor adventures. Made from durable stainless steel with double-wall vacuum insulation, it keeps drinks hot or cold all day. Innovative MagSlide lid for reliable closing. Lid design prevents splashes and spills. Innovative MagSlider lid uses magnets to keep it reliably open or closed. MagSlider lid is made from shatter-resistant material. Rugged stainless steel construction resists dents and dings. Double-wall vacuum insulation keeps cold drinks cold and hot drinks hot until the last sip. No Sweat™ design prevents condensation, keeps hands dry and comfortable. Dishwasher safe. Imported. | Yeti Rambler Tumbler With MagSlide Lid, 20 oz. Navy, Stainless Steel', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/0d082a21a59c29132db4ce36da8b729e854e58ab6fd427ef9e68ba84f8b6a8f7.webp', '2026-08-11', 2);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('ae133374b3402eddd0187f5f', 'l-l-bean', 'L.L.Bean', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/58f4640011088508b7019e0e8a94a983c5ac643e280073d3b8b2d05cfc353d0d.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/l-l-bean', 'https://llbean.com/', 'llbean.com', 'Yeti Rambler Chug Bottle, 36 oz. Navy', 'Double-wall vacuum insulation that keeps drinks cold all day plus a generous capacity will make this your everyday water bottle. The new Chug Cap makes drinking even easier, just a quick half-twist of the TripleHaul handle and you''re ready. Double-wall vacuum insulation keeps drinks cold all day. Over-The-Nose™ Technology offers an extra-wide mouth for easy ice loading and unobstructed drinking. Made from tough stainless steel. Dishwasher safe. Chug Cap is not intended for use with hot beverages. Cap is shatter-resistant and dishwasher safe. Chug Cap allows super-easy, on-the-go drinking. Imported. | Yeti Rambler Chug Bottle, 36 oz. Navy', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/ea8fdc84aaa9f25f1a0bd630db5746d16833c3c8962c6efb257a2644c398f657.webp', '2026-08-11', 2);
