INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('aec8dfb6c77615f61d6c0a3b', 'l-l-bean', 'L.L.Bean', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/58f4640011088508b7019e0e8a94a983c5ac643e280073d3b8b2d05cfc353d0d.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/l-l-bean', 'https://llbean.com/', 'llbean.com', 'Yeti Rambler Tumbler With MagSlide Lid, 20 oz. Navy, Stainless Steel', 'The Yeti Rambler is tough enough to keep up with the most intense of your outdoor adventures. Made from durable stainless steel with double-wall vacuum insulation, it keeps drinks hot or cold all day. Innovative MagSlide lid for reliable closing. Rugged stainless steel construction resists dents and dings. Innovative MagSlider lid uses magnets to keep it reliably open or closed. Lid design prevents splashes and spills. Double-wall vacuum insulation keeps cold drinks cold and hot drinks hot until the last sip. MagSlider lid is made from shatter-resistant material. No Sweat™ design prevents condensation, keeps hands dry and comfortable. Dishwasher safe. Imported. | Yeti Rambler Tumbler With MagSlide Lid, 20 oz. Navy, Stainless Steel', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/0d082a21a59c29132db4ce36da8b729e854e58ab6fd427ef9e68ba84f8b6a8f7.webp', '2026-08-17', 1);
