INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('3fc2eda446e113e2c2789519', 'faire-wholesale-inc', 'Faire Wholesale, Inc.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/4f9df830b2b3c063e6a8ab24719595d581ed92cd601595fef007d7f76ac8bcb7.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/faire-wholesale-inc', 'https://www.faire.com/', 'faire.com', 'Reel Bamboo Toilet Paper - 12 Rolls', 'Reel Paper brings you the Reel Bamboo Toilet Paper - 12 Rolls, a testament to our mission to end deforestation and single-use plastics. Crafted from 100% bamboo, this toilet paper reduces greenhouse gas emissions and doesn''t require replanting after harvest. It''s not just eco-friendly, but also offers 3-ply softness and strength that rivals traditional toilet paper. Packaged without plastic, it further enhances our commitment to the environment. Plus, with over 10,000 5-star reviews, our customers clearly appreciate the comfort and durability. Choose Reel, choose a greener planet.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/2e8db723f3895724429ea03e864bbdaf8484779e9b53b4059d255926f2c5e91b.webp', '2026-08-17', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('cdd382b5c3fe286617a86281', 'faire-wholesale-inc', 'Faire Wholesale, Inc.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/4f9df830b2b3c063e6a8ab24719595d581ed92cd601595fef007d7f76ac8bcb7.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/faire-wholesale-inc', 'https://www.faire.com/', 'faire.com', 'Premium 100% Bamboo Toilet Paper - 8 pack (4/case)', 'Smooth and strong, our premium rolls are super cushy and made from 100% bamboo. Our softest loo roll ever—it’s like wiping with clouds. Case Pack: 4 sales units/case Unit Cost: $10.06 SRP: $14.49 • Luxuriously soft and ultra-strong 3-ply • Made from 100% renewable and sustainable bamboo • 20% more sheets than the average roll • Bespoke black and white packaging design, plastic-free • 360 sheets per roll • 50% of profits donated', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/56c7ddad2a456e961f9047a0e15bfe40c051331c43c5a14b51d8a8a6a7688f78.webp', '2026-08-17', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('bb89bfcaca4a52e4b045e2b1', 'faire-wholesale-inc', 'Faire Wholesale, Inc.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/4f9df830b2b3c063e6a8ab24719595d581ed92cd601595fef007d7f76ac8bcb7.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/faire-wholesale-inc', 'https://www.faire.com/', 'faire.com', 'Bamboo Paper Towel', 'Toxin-free, minimally processed, and never bleached. Better for body and environment. * Case of 12 - Ready to Retail with scannable barcode on individual rolls as well as case * Certified PFA-Free * 100% Biodegradable * Septic-Safe * Black and Greywater Safe * 100% Unbleached, real brown bamboo color Panda Eco Paper vs Another Leading Brand of Paper Towels | Ours is certified PFAS-free (No forever chemicals), certified formaldehyde-free, and certified heavy metal-free. Last but not least, no paper wrapping here! Verified FREE of Harmful Chemicals | Ours is certified PFAS-free (No forever chemicals), certified formaldehyde-free, and certified heavy metal-free. See our third-party testing for PFAS and the testing for Heavy Metals. Is your Bamboo organic? | While this product is not USDA "certified" organic, bamboo is naturally "organic" because of its innate defenses against pests and diseases; an antimicrobial substance called "kun" helps protect it from harmful organisms. The Farms | We are sustainably sourced; our bamboo comes from ethical farms that do NOT utilize slave labor. The ground itself is not mono-cropped and is not replacing forest space. It is a carbon-negative production that does not disrupt wildlife (pandas) or nature (old-growth/protected forest). The farms let their bamboo grow naturally. Toxin + Irritant Free | Commercial paper towels often contain undisclosed hidden chemicals. Our paper towels are Paraffin-Free ∙ Wax-free ∙ Formaldehyde-free ∙ Dioxane-free ∙ PEGs-free ∙ PFAS-free ∙ Perfume-free ∙ Fragrance-free ∙ Chlorine-free ∙ Bleach-free ∙ Heavy metal-free ∙ PCP-free — and simply worry-free.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/681b5a1dc683e12f98c8e6685ebd7f09125d4e5bc9adcfa870d42f5f0d08e59f.webp', '2026-08-17', 1);
