INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('d17642cbcaaff1257ea4128c', 'faire-wholesale-inc', 'Faire Wholesale, Inc.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/4f9df830b2b3c063e6a8ab24719595d581ed92cd601595fef007d7f76ac8bcb7.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/faire-wholesale-inc', 'https://www.faire.com/', 'faire.com', 'Moose Cotton Compression Socks', 'Love those majestic moose? Show your appreciation (and feel great while you''re at it) with these novelty knee-high compression socks. They come in a super-soft cotton blend for comfort and breathability. Plus, they provide moderate graduated compression — 15-20 mmHg — to help soothe your ankles and calves.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/8574bca45f32a0a59baf8c88fddde7e06683f07dd7d7fb8884cc8f58f88a2701.webp', '2026-08-16', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('0955540835d96505e76fe3b8', 'faire-wholesale-inc', 'Faire Wholesale, Inc.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/4f9df830b2b3c063e6a8ab24719595d581ed92cd601595fef007d7f76ac8bcb7.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/faire-wholesale-inc', 'https://www.faire.com/', 'faire.com', 'Floral Cotton Compression Socks', 'Are your legs feeling tired and achy? Try these pretty floral knee socks. The soft cotton-blend fabric delivers graduated moderate compression to help promote blood circulation, ease soreness, and relieve painful swelling. The comfort cuff stays up without squeezing, while the cozy cushioned sole soothes your every step.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/ef6542a8c5b49f16d6943da4a9300463ba14327fd16be49547220cbe4febf27f.webp', '2026-08-16', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('ade114d4389b54466a3d47e3', 'faire-wholesale-inc', 'Faire Wholesale, Inc.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/4f9df830b2b3c063e6a8ab24719595d581ed92cd601595fef007d7f76ac8bcb7.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/faire-wholesale-inc', 'https://www.faire.com/', 'faire.com', 'USA Made Alpaca Compression Socks', 'We are delighted to offer these made in the USA alpaca compression socks. Alpaca Compression Socks — Performance Meets Natural Luxury Experience a new standard of comfort on the move. Our alpaca compression socks combine the refined softness of premium alpaca fiber with thoughtfully engineered compression, designed for those who demand performance without sacrificing feel. Whether you’re navigating long travel days, pushing through demanding trails, or simply spending hours on your feet, these socks deliver consistent support with a naturally elevated touch. Why people love alpaca compression socks: Targeted Compression Support Graduated compression provides a gentle, structured fit that supports circulation and helps reduce the sensation of fatigue during extended wear. Naturally Thermoregulating Alpaca fiber adapts to your environment—keeping your feet warm in cooler conditions and comfortably breathable when temperatures rise. Exceptionally Soft, Zero Itch Smoother than traditional wool and free of lanolin, alpaca offers a refined, irritation-free feel which is ideal for sensitive skin. Dry, Fresh Comfort Moisture-wicking and odor-resistant properties help keep feet dry and fresh, whether you’re on the trail or in transit. Built for Endurance Reinforced cushioning, heels and toes plus a secure fit help minimize friction, supporting all-day wear across varied terrain. Designed for the Journey From alpine air to long-haul travel, these alpaca socks are made for movement—crafted to perform, designed to last, and finished with the quiet luxury of nature’s most remarkable fiber! Key Features: * Progressive compression from 15-20 mmHg of support * Reduction of pressure from ankle to top of sock *', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/194e00860ea6161c75af01eaf63b0f34d99b783adc89294a5f4c40639b39566a.webp', '2026-08-16', 1);
