INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('ecc4b31fa1d0b90b0d179a9f', 'home-depot', 'Home Depot', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/2629c31e537475e2fb5c3d690c6ccecf8d8389186b5ee30e342d7e8d293abf0a.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/home-depot', 'https://www.homedepot.com/', 'homedepot.com', 'futhork 23.5 in. Dual Open Built-in/Freestanding Outdoor Beverage Center in Stainless Steel with Adjustable Temperature', 'Experience ultimate convenience with our versatile wine and beverage refrigerator, featuring dual cooling zones for customized storage. The left zone, adjustable from 35°F to 50°F, is perfect for various beverages, while the right zone, between 41°F and 64°F, is ideal for wines. This 24 in. unit holds up to 96 standard 12 oz. cans on the left and 22 standard 750 ml wine bottles on the right. Its energy-efficient compressor meets global standards for cost savings and eco-friendliness, operating quietly at 40dB. The smart touch control screen offers precise temperature adjustments, with elegant blue LED lighting for better visibility. A safety door lock adds security, and the stainless steel design is durable, rust-resistant, and easy to clean. The front ventilation allows seamless integration into any space, making it perfect for kitchens, living rooms, or garages. Enhance your beverage experience with this sleek, advanced refrigerator.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/a3283a0fee816b2ae911b4df3c93872f932213cc356876a493e13cdbf6892f1d.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('f714b587245bdd2da6add859', 'home-depot', 'Home Depot', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/2629c31e537475e2fb5c3d690c6ccecf8d8389186b5ee30e342d7e8d293abf0a.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/home-depot', 'https://www.homedepot.com/', 'homedepot.com', 'Hooure 24 in. 190 Cans Built-In/Freestanding Outdoor Beverage Center in Stainless Steel with Digital Temperature Control', 'Our fast-cooling outdoor refrigerators combine modern features with powerful cooling performance. The compressor system ensures that beverages and food are quickly cooled to 37°F within 6-hours, even when fully loaded. Constructed of outdoor-grade 304 stainless steel, it features a corrosion-, rain- and rust-resistant design for use in a variety of environments. Intelligent temperature memory ensures your settings won''t be affected by power outages and mobility-enhancing wheels make it easy to move. And next to the wheels are devices that keep it in place. It also features automatic lighting for a stylish alternative. Holds up to 190 standard 12 oz. cans for a variety of spaces. Ideal for the home, office, dorm or bar. With our fast-cooling outdoor refrigerator, you can enjoy chilled beverages and leisure time wherever you go.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/0753aef7e28fc56e2b35f9627618fbb07c57fa2e6cf5452bd9cf902f0a813078.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('0455cd66cd2b9a787c20fa3f', 'home-depot', 'Home Depot', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/2629c31e537475e2fb5c3d690c6ccecf8d8389186b5ee30e342d7e8d293abf0a.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/home-depot', 'https://www.homedepot.com/', 'homedepot.com', 'Denjol 23.4 in. Dual Zone Built-In/Freestanding Indoor and Outdoor Beverage Center with French Door Beverage Cooler', 'The 24-in. dual-zone wine and beverage fridge is the perfect upgrade for your home, bar, or restaurant. With independently controlled temperature zones, you can store wine and beverages at their ideal temperatures. Elegant wooden wine racks and sturdy wire beverage shelves offer organized storage, while the powerful compressor and smart fan system ensure stable cooling. Its front-venting design fits seamlessly into built-in or freestanding setups. The sleek touch control and ambient blue LED lighting bring a touch of luxury to any space. Material: Stainless Steel.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/35014f0897f010925bcd625d66b47846b38f34bb81be29373625280102e9aa7e.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('208ec641c682bb5a1a6d8ada', 'home-depot', 'Home Depot', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/2629c31e537475e2fb5c3d690c6ccecf8d8389186b5ee30e342d7e8d293abf0a.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/home-depot', 'https://www.homedepot.com/', 'homedepot.com', 'Hooure 24 in. 5.3 cu. ft. 178 Cans Built-In/Freestanding Outdoor Beverage Center in Stainless Steel with Dual Drawer', 'This large capacity drawer refrigerator features 2-drawers that can hold up to 178 cans of beverages. Equipped with divider shelves, it allows you to store a variety of beverages in an organized manner. Our refrigerator features an upgraded compressor and fan circulation system to ensure quiet and fast cooling. It also produces minimal vibration and noise during operation, with noise levels consistently kept below 38 db. The refrigerator door features a high-quality stainless steel French door design made of outdoor-grade 304 stainless steel with an IPX4 waterproof rating that is resistant to corrosion, rain and rust. This 24 in. W beverage refrigerator can be easily placed under the counter to save space and is perfect for a variety of locations, including kitchens and outdoor grilling areas.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/862ec89682ef0648675d6ab979ad696399bf87399b2f25cee753e73a65af4c89.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('677a80e86305e6fbdbe37077', 'home-depot', 'Home Depot', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/2629c31e537475e2fb5c3d690c6ccecf8d8389186b5ee30e342d7e8d293abf0a.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/home-depot', 'https://www.homedepot.com/', 'homedepot.com', 'Hooure 24 in. 4.9 cu. ft. Built-in/Freestanding Indoor/Outdoor Beverage Refrigerator for 186-Cans (Glass Door)', 'Upgrade your beverage storage with our high-capacity cooler, holding up to 180 cans of drinks and beer-ideal for gatherings, parties, or everyday use. Featuring adjustable metal shelves for flexible storage, it offers a powerful cooling system with a stable temperature range of 37-64°F to keep your drinks perfectly chilled. Frost-free air-cooling technology reduces maintenance while keeping beverages fresh.With a sleek stainless steel frame, this cooler adds modern elegance to any space. Operating quietly at under 38 dB, it ensures a peaceful environment. The double-layer tempered glass stabilizes internal temperature, while the built-in exhaust fan promotes air circulation and prevents odors. A memory function restores settings after a power outage, ensuring reliability. Whether built-in or standalone, it fits seamlessly into your space, combining style and function for a premium experience.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/69d43c7fb4cd13cff7a1be54c99113808a2c0245bf2c2e5528e4353792a44cb3.webp', '2026-08-09', 1);
