INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('7cafbf59d659b561798c4591', 'home-depot', 'Home Depot', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/2629c31e537475e2fb5c3d690c6ccecf8d8389186b5ee30e342d7e8d293abf0a.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/home-depot', 'https://www.homedepot.com/', 'homedepot.com', 'Coleman Vintage 54 qt. Steel Belted Hard Cooler, Green', 'Embrace the past while celebrating the present with the Coleman Vintage 54-Quart Steel Belted Cooler. This high-capacity, heavy-duty cooler features a charming retro design with modern performance capabilities. It''s perfect for camping, BBQs, tailgating, beach days, backyard parties and outdoor festivals. With a 54-quart capacity that accommodates up to 85 cans, you''ll never run out of chilled beverages. Keeps the Ice insulation provides 4-day ice retention, even in heatwaves of up to 90 degrees Fahrenheit. The Have-A-Seat lid doubles as an extra chair, supporting up to 250 lbs. The cooler is crafted for easy, controlled mobility with comfort-grip steel handles. Built to last with rust-resistant stainless steel hardware, the cooler delivers teamed performance for years of your adventures. Color: Green.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/3f3ca044f091de8d872d0dc6d3d9df825846eea53c74d9346f6b5d038e9467de.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('484b5966d7b2ad56e646777e', 'home-depot', 'Home Depot', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/2629c31e537475e2fb5c3d690c6ccecf8d8389186b5ee30e342d7e8d293abf0a.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/home-depot', 'https://www.homedepot.com/', 'homedepot.com', 'Ivation Electric Cooler (45 L), Thermoelectric Cooler, 12V Cooler and Car Fridge', 'If you need a car cooler in your next road trip, picnic or camping trip, pack your snacks and drinks in the portable cooler and warmer from ivation. This portable refrigerator has a 45 liter interior compartment that allows for ample storage space. The dual function 12-Volt cooler heats up to 130 °F to keep your food hot and cools to 40 °F to keep your drinks cold. The plug in cooler easily allows you to plug in anywhere in your home or vehicle if you need an electric cooler for camping. Color: Blue.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/f5d72571ede217c6ef0af81b3f9e6ac4a98270db45952cfa1fe96a33c030ba95.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('1f595c57d29a8145c35a73b1', 'home-depot', 'Home Depot', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/2629c31e537475e2fb5c3d690c6ccecf8d8389186b5ee30e342d7e8d293abf0a.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/home-depot', 'https://www.homedepot.com/', 'homedepot.com', 'Klein Tools Insulated Jobsite Cooler Kit, 3-Piece', '3-Piece Klein Tools Cooler with Tumbler Kit is durable to bring to the jobsite. This lunch box is a serious cooler that keeps items cool for up to 30 hours. The 20-Ounce Tumbler keeps liquid cold up to 12 hours and hot up to 4 hours. Stainless-Steel Beverage Tool makes an excellent addition to the arsenal of an apprentice or experienced professional barkeep. Color: Gray and Orange.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/bde91959df7480d6d18e18f7f73d80cf83bdb070898ac2c014bb3c9bd758e371.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('9233d8eeab70e767af22fa85', 'home-depot', 'Home Depot', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/2629c31e537475e2fb5c3d690c6ccecf8d8389186b5ee30e342d7e8d293abf0a.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/home-depot', 'https://www.homedepot.com/', 'homedepot.com', 'Karl home Black 80 Qt. Iron Beverage Wheeled Cooler with Shelf', 'Are you looking for a high quality freezer incubator? This Black 80 Qt. Iron Beverage Wheeled Cooler with Shelf is highly recommended to you! Adopting high quality iron spray material, it features stable, sturdy, durable and environment friendly. Besides, it has two directional wheels, so you can stop at any time. It also features bottom tray design, convenient to carry things. What''s important, it has warm and cooling functions. It can keep the warm food above 40 ℃ for 4-5 hours and preserve cool for up to 48 hours with ice sheet. So what are you waiting for? Don''t hesitate, it''s worth buying.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/fdac17e56fb3211503abc963bb9984bec9c91e0d2c204519333bce9503e6f0bb.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('00d33937cd474743d7c3848a', 'dragon-spirits-marketing-inc', 'Dragon Spirits Marketing Inc.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/902c89bafcc87c12fe78df4a0de8f07b2d812113b5e5013cc149ab3b970b3a4e.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/dragon-spirits-marketing-inc', 'https://www.hiredragons.com/', 'hiredragons.com', 'Scale Your Tastings', 'One staffing partner for beverage programs across multiple markets.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/1bc2e0f054adacbb5c781a3904ce54c66f9980d6584c46c7fe423c24a3e4dc0c.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('0d2fb62962cd9cb7dbe8305f', 'thriftbooks', 'ThriftBooks', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/039f93ce508eeba45d26084a3fce9939269c3a4e7e0de23e21e748d91d6322f9.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/thriftbooks', 'https://www.thriftbooks.com/', 'thriftbooks.com', 'The Wildcrafting Brewer: Creating Unique Drinks and Boozy Concoctions from Nature''s Ingredients by Baudar, Pascal by Chelsea Green Publishing Company', 'This home brewing guide "takes wild fermentation to the next level," offering "gorgeous photos and clear technical details" for delicious primitive concoctions (Sandor Ellix Katz, author of The Art of Fermentation). Learn how to brew primitive beers, country wines, herbal meads, and more Fermentation fans and home brewers can rediscover "primitive" drinks and their unique flavors in The Wildcrafting Brewer. Wild-plant expert and forager Pascal Baudar''s first book, The New Wildcrafted Cuisine, opened up a whole new world of possibilities for readers wishing to explore and capture the flavors of their local terroir. The Wildcrafting Brewer does the same for fermented drinks. Baudar reveals both the underlying philosophy and the practical techniques for making your own delicious concoctions, including: - Wild sodas- Country wines- Primitive herbal beers- Meads- Traditional ferments like tiswin and kvass The book opens with a retrospective of plant-based brewing and ancient beers. The author then goes on to describe both hot and cold brewing methods and provides lots of interesting recipes; mugwort beer, horehound beer, and manzanita cider are just a few of the many drinks represented. Baudar is quick to point out that these recipes serve mainly as a touchstone for readers, who can then use the information and techniques he provides to create their own brews, using their own local ingredients. The Wildcrafting Brewer will attract herbalists, foragers, natural-foodies, and chefs alike with the author''s playful and relaxed philosophy. Readers will find themselves surprised by how easy making your own natural drinks can be, and will be inspired, again, by the abundance of nature all around them. By Chelsea Green Publishing Company [ 9781603587181 ]', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/208f890fa398a7d707d7a55462e58133597a18520908cac10b80b0298fedc9b9.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('32b8222186dd65c394d0d397', 'thriftbooks', 'ThriftBooks', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/039f93ce508eeba45d26084a3fce9939269c3a4e7e0de23e21e748d91d6322f9.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/thriftbooks', 'https://www.thriftbooks.com/', 'thriftbooks.com', 'Wildcrafted Fermentation: Exploring, Transforming, and Preserving the Wild Flavors of Your Local Terroir by Baudar, Pascal by Chelsea Green Publishing Company', 'Learn how to make flavorful fermented foods-from wild edibles -with this fermentation cookbook featuring 100+ plant-based recipes for krauts and kimchis, brines, cheeses, and more. "I am in awe of this book"―Sandor Katz, author of The Art of Fermentation One of the most influential tastemakers of our time invites you on an extraordinary culinary journey into the lacto-fermentation universe of common wild edibles. Used for thousands of years by different cultures all around the world, lacto-fermentation is the easiest, safest, and most delicious way to preserve food. And nature provides all the necessary ingredients: plants, salt, and the beneficial lactic acid bacteria found everywhere. In Wildcrafted Fermentation, Pascal Baudar describes in detail and through step-by-step color photos how to create rich flavorful ferments: - At home- From the wild plants in your local landscape- From the cultivated plants in your garden From sauerkrauts and kimchis to savory pastes, hot sauces, and dehydrated spice blends, Baudar includes more than 100 easy-to-follow, plant-based recipes to inspire even the most jaded palate. The step-by-step photos illustrate foraging, preparation, and fermentation techniques for both wild and cultivated plants that will change your relationship to the edible landscape and give you the confidence to succeed like a pro. So much more than a cookbook, Wildcrafted Fermentation offers a deeply rewarding way to reconnect with nature through the greens, stems, roots, berries, fruits, and seeds of your local terroir. Adventurous and creative, this cookbook will help you rewild your probiotic palate and "create a cuisine unique to you and your environment." By Chelsea Green Publishing Company [ 9781603588515 ]', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/b8c5308b4d0daa41be664b50743dc676d8b42981b90ca062dcafe063cf1214be.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('9d57f76c4b41faeaa3516577', 'thriftbooks', 'ThriftBooks', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/039f93ce508eeba45d26084a3fce9939269c3a4e7e0de23e21e748d91d6322f9.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/thriftbooks', 'https://www.thriftbooks.com/', 'thriftbooks.com', 'Wildcrafted Fermentation: Exploring, Transforming, and Preserving the Wild Flavors of Your Local Terroir by Baudar, Pascal by Chelsea Green Publishing Company', 'This used book is in Acceptable condition. Learn how to make flavorful fermented foods-from wild edibles -with this fermentation cookbook featuring 100+ plant-based recipes for krauts and kimchis, brines, cheeses, and more. "I am in awe of this book"―Sandor Katz, author of The Art of Fermentation One of the most influential tastemakers of our time invites you on an extraordinary culinary journey into the lacto-fermentation universe of common wild edibles. Used for thousands of years by different cultures all around the world, lacto-fermentation is the easiest, safest, and most delicious way to preserve food. And nature provides all the necessary ingredients: plants, salt, and the beneficial lactic acid bacteria found everywhere. In Wildcrafted Fermentation, Pascal Baudar describes in detail and through step-by-step color photos how to create rich flavorful ferments: - At home- From the wild plants in your local landscape- From the cultivated plants in your garden From sauerkrauts and kimchis to savory pastes, hot sauces, and dehydrated spice blends, Baudar includes more than 100 easy-to-follow, plant-based recipes to inspire even the most jaded palate. The step-by-step photos illustrate foraging, preparation, and fermentation techniques for both wild and cultivated plants that will change your relationship to the edible landscape and give you the confidence to succeed like a pro. So much more than a cookbook, Wildcrafted Fermentation offers a deeply rewarding way to reconnect with nature through the greens, stems, roots, berries, fruits, and seeds of your local terroir. Adventurous and creative, this cookbook will help you rewild your probiotic palate and "create a cuisine unique to you and your environment." By Chelsea Green Publishing Company [ 9781603588515 ]', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/b8c5308b4d0daa41be664b50743dc676d8b42981b90ca062dcafe063cf1214be.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('daf95a20acd3538190334406', 'thriftbooks', 'ThriftBooks', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/039f93ce508eeba45d26084a3fce9939269c3a4e7e0de23e21e748d91d6322f9.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/thriftbooks', 'https://www.thriftbooks.com/', 'thriftbooks.com', 'Botanical Bar Craft: A Guide to the Art of Apothecary Cocktails and Herbal Tonic Elixirs by Sears, Cassandra Elizabeth by Chelsea Green Publishing Company', 'For cocktail enthusiasts, herbalists, foragers, and bartenders, Botanical Bar Craft serves up original, spirited recipes and invaluable plant knowledge, inspired by adventures in the garden and forest. In Botanical Bar Craft, innovative herbalist and mixologist Cassandra Sears invites readers to create herbal elixirs and apothecary cocktails infused by a close connection to nature. Whether in the garden, the field, or the forest, Sears finds generous abundance among the plants. Her tonic libations harness the power of phytochemistry and place-based consciousness while easing stress and comforting the body, mind, and spirit. With original recipes that tie together the creative arts of herbal medicine and craft cocktail making, Sears blends herbal tinctures, teas, and botanical infusions into modern-classic cocktails as well as sensational and unique nonalcoholic drinks that hit the spot for relaxation without sedation. More than just a collection of recipes, Botanical Bar Craft is also an herbal handbook for bartenders and a mixology guide for herbalists. Readers will delight in the journey as Sears combines dashes of herbal lore and history with instructions for developing the spirited philosophy of apothecary bartending, lessons on mixology, and a primer on the beneficial actions of medicinal herbs. Inside Botanical Bar Craft, you''ll also find: 65 original recipes for potions, tonics, elixirs, and cocktails, including Kava Cacao Flip, Pregnancy Punch, Victory Garden, Bloody Botanist, Bitters and Soda, Juice of Life, and Euphoria. More than 40 plant profiles that include how those plants grow and suggestions for how to use them behind the bar to draw out their beneficial actions. An accessible explanation of the chemistry and energetics of medicinal herbs. Behind-the-scenes interviews with artisan distillers. Advice and tips for growing a garnish garden. This book will not only appeal to herbalists, herbal enthusiasts, and home cocktail enthusiasts, but also to professional bartenders looking to embrace the use of innovative and highly flavorful natural ingredients in their bar creations. Botanical Bar Craft provides all the answers for those who are curious and wondering how to make a really good drink inspired by and infused with plants. "Unique among cocktail books-it helps readers reconnect their creative selves with the natural environment and healing plants. . . Sears] equips you with the proper bar techniques to harness the power and fleeting beauty of your surroundings."-Brian Catapang, bar director and co-owner at Magnus on Water By Chelsea Green Publishing Company [ 9781645022398 ]', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/d5ff6d2f0ba0bed2c3b9042e30e7fda6a65de3f5d5e2f67a46d93f1cf7e0c661.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('95f7078ebaac0817d6672d0d', 'thriftbooks', 'ThriftBooks', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/039f93ce508eeba45d26084a3fce9939269c3a4e7e0de23e21e748d91d6322f9.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/thriftbooks', 'https://www.thriftbooks.com/', 'thriftbooks.com', 'True Brews: How to Craft Fermented Cider, Beer, Wine, Sake, Soda, Mead, Kefir, and Kombucha at Home by Christensen, Emma by Ten Speed Press, Hardcover', 'This used book is in Very Good condition. This accessible home-brew guide for alcoholic and non-alcoholic fermented drinks, from Apartment Therapy- The Kitchn''s Emma Christensen, offers a wide range of simple yet enticing recipes for Root Beer, Honey Green Tea Kombucha, Pear Cider, Gluten-Free Sorghum Ale, Blueberry-Lavender Mead, Gin Sake, Plum Wine, and more. Making naturally fermented sodas, tending batches of kombucha, and tackling homebrewed beer are the next frontier for the homemade revolution. Food writer Emma Christensen shows that these projects can be all done in the smallest apartment kitchen with little more equipment than a soup pot, a plastic bucket, and a long-handled spoon. This book captures that crafty, adventurous spirit that makes the brewing arts accessible. Since all 50-plus recipes stem from the same basic technique and use the same simple equipment, it''s easy for cooks to make the leap from project to project. By covering a rage of homemade beverages, from quick and easy kefir to cellared fruit wines, True Brews is sure to be a hit with the DIY crowd. By Ten Speed Press [ 9781607743385 ]', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/4062ac942cf561e1239972770e4cd5e74e3fbb7fcb32c19e00a6e424332da88e.webp', '2026-08-09', 1);
