INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('65393b36197871516b388cc3', 'l-l-bean', 'L.L.Bean', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/58f4640011088508b7019e0e8a94a983c5ac643e280073d3b8b2d05cfc353d0d.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/l-l-bean', 'https://llbean.com/', 'llbean.com', 'L.L.Bean Stowaway Pack, Print Medium Blue Grid', 'With a new superlight, extra rugged recycled ripstop polyester fabric and a cleaner design, our customer favorite Stowaway pack is better than ever. It''s still impossibly light and stuffs away into its own small internal pocket, making it the perfect choice for travel. Spot clean. Panel-load design. Back panel with wicking Air Mesh for all day comfort. Lots of pockets for organizing gear featuring an easily accessible front "shove it" pocket. Padded foam shoulder straps and back panel for increased comfort. Shell is bluesign®-approved 75D recycled polyester ripstop. "Blinky" loop for attaching a light to help keep you visible. Adjustable waistbelt and sternum strap hold pack secure against your body. Features an internal stow pocket so you can stuff it into a tiny package for travel. Two side mesh water-bottle pockets with new loop locks to keep bottles secure. Imported. | L.L.Bean Stowaway Pack, Print Medium Blue Grid', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/8bab17c5c4daafe7a830491d4919cff6b89ebf4ffaa82f80b02b7557e11530be.webp', '2026-08-09', 1);
