INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('835b4b65d004c0ae86c281fc', 'faire-wholesale-inc', 'Faire Wholesale, Inc.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/4f9df830b2b3c063e6a8ab24719595d581ed92cd601595fef007d7f76ac8bcb7.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/faire-wholesale-inc', 'https://www.faire.com/', 'faire.com', 'Reusable Paper Towels - Pre-Rolled 24-Pack', 'It''s time to ditch the single-use paper towels for this organic, reusable alternative. Every day, over 51,000 trees are cut down to support America''s paper towel habit, and it''s completely unnecessary! This swap saves trees, precious water resources, and helps save you money. Made with GOTS certified organic cotton, our 1-ply reusable paper towels are perfect for cleaning messes, drying hands, or any time you''re in need of a paper towel. Once dirty, simply wash with your normal laundry and reuse for years. Plus, the cotton material naturally clings together, making it super easy to re-roll onto the cardboard paper towel tube. 𝐂𝐡𝐨𝐨𝐬𝐞 𝐟𝐫𝐨𝐦: • Comes in pack of 24 rolled onto a cardboard tube; • Available in Earth Tones, Greys, or White.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/e305fdd99545d6f253e1fa890c639254aaa0bdfb53e7f3a10a9afebd71e7fc40.webp', '2026-08-09', 1);
INSERT OR REPLACE INTO ads (id, advertiser_slug, advertiser_name, advertiser_logo, advertiser_page_url, website_url, website_domain, copy, description, media_url, published_date, impressions) VALUES ('107889ef67a2fa36b42ead0a', 'faire-wholesale-inc', 'Faire Wholesale, Inc.', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/4f9df830b2b3c063e6a8ab24719595d581ed92cd601595fef007d7f76ac8bcb7.webp', 'https://supaintent.com/tools/chatgpt-ads-library/advertisers/faire-wholesale-inc', 'https://www.faire.com/', 'faire.com', 'Unbleached Bamboo Paper Towels (8 rolls/box)', 'Switching to tree-free paper towels is a small change that has a big impact on the future of our forests. We''re cutting down millions of trees every year that take decades to grown and mature just to clean up 30 second messes. Betterway''s 100% bamboo paper towels has all the best features with the added bonus of being a more sustainable option. It''s packaged plastic-free and each individual roll wrapper is compostable. We''ve done our best to create a product that doesn''t sacrifice quality for sustainability. 𝐏𝐫𝐨𝐝𝐮𝐜𝐭 𝐝𝐞𝐭𝐚𝐢𝐥𝐬: • FSC certified, 100% bamboo fibers • natural brown / unbleached • 90 tree-tree sheets per roll • 2-ply and embossed texture for extra strength • No inks, dyes, or scents • BPA-free & hypoallergenic • Plastic-free packaging • Able to be composted at home', 'https://mycisixpwfbujadhezrz.supabase.co/storage/v1/object/public/ai-runs-public-ads/assets/7f3a2a6cc0b40da9f2993f2c6ab5387dd4915ff835d70243f8e25e914024363d.webp', '2026-08-09', 1);
